+// Lección candidata L-motivo-minimo: el motivo se recorta y debe tener al menos 10 caracteres.
+const MOTIVO_MINIMO = 10;
+
+function validarMotivo(motivo) {
+  const limpio = typeof motivo === "string" ? motivo.trim() : "";
+  if (limpio.length < MOTIVO_MINIMO) throw new Error(`El motivo debe tener al menos ${MOTIVO_MINIMO} caracteres`);
+  return limpio;
+}
+
+// RF-006: ajusta el stock al recuento físico agregando un movimiento por la diferencia (ADR-001).
+// Si el recuento coincide con el stock calculado, devuelve la misma lista sin agregar nada.
+export function ajustarInventario(movimientos, { articulo, almacen, cantidadContada, motivo }) {
+  if (!Number.isInteger(cantidadContada) || cantidadContada < 0)
+    throw new RangeError("La cantidad contada debe ser un entero mayor o igual a cero");
+  const limpio = validarMotivo(motivo);
+  const diferencia = cantidadContada - stock(movimientos, articulo, almacen);
+  if (diferencia === 0) return movimientos;
+  return registrarMovimiento(movimientos, {
+    tipo: diferencia > 0 ? "ingreso" : "egreso",
+    articulo,
+    almacen,
+    cantidad: Math.abs(diferencia),
+    motivo: limpio,
+  });
+}
